fn getdomain(x: Vec<i8>) -> Vec<i8> {
    // Since the input vector is guaranteed non-empty, we can safely
    // initialize `min_val` and `max_val` to the first element.
    let mut min_val = x[0];
    let mut max_val = x[0];

    // Iterate over the rest of the elements and update min and max accordingly.
    for &v in &x[1..] {
        if v < min_val {
            min_val = v;
        }
        if v > max_val {
            max_val = v;
        }
    }

    // Return a two-element Vec containing [min, max].
    vec![min_val, max_val]
}

